-- ============ DROP / CARRY ============
local function findDropButton()
    for _, v in ipairs(plr.PlayerGui:GetDescendants()) do if v:IsA("TextButton") and (v.Name:lower():find("drop") or v.Text:lower():find("drop")) then return v end end
    return nil
end
local function isDropVisible()
    local b = findDropButton()
    if not b or not b.Visible then return false end
    local cur = b.Parent
    while cur and cur ~= plr.PlayerGui do if cur:IsA("GuiObject") and not cur.Visible then return false end cur = cur.Parent end
    return true
end
local function fireDropNow()
    local b = findDropButton()
    if b then pcall(function() b:Activate() end) end
    local r = RS:FindFirstChild("DropCarriedRemote") or RS:FindFirstChild("DropCarriedRemote", true) or RS:FindFirstChild("DropCarried", true)
    if r then pcall(function() r:FireServer() end) end
end
local function closestAnimal(maxDist)
    local hrp = findHRP(plr.Character)
    if not hrp then return nil end
    local folder = workspace:FindFirstChild("AnimalPickups")
    if not folder then return nil end
    local best, md = nil, maxDist or 8
    for _, m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") then local p = posOf(m) if p then local d = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(p.X, 0, p.Z)).Magnitude if d < md then md = d best = m end end end
    end
    return best
end
local function isCarryingTarget(t)
    if not isDropVisible() then return false end
    local c = closestAnimal(8)
    if not c then return true end
    if c == t then return true end
    if c.Name == t.Name and c:GetAttribute("Rarity") == t:GetAttribute("Rarity") then return true end
    return false
end

-- ============ WALK ============
local function walkDirect(targetPos, lookAt, keepRot)
    local hrp = findHRP(plr.Character)
    if not hrp or not targetPos then return end
    if lookAt then lookAt = Vector3.new(lookAt.X, targetPos.Y, lookAt.Z) end
    pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero end)
    local function distLeft() return (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(targetPos.X, 0, targetPos.Z)).Magnitude end
    if distLeft() < 1.2 then return end
    while distLeft() > 1.2 do
        if not plr.Character or not hrp.Parent then break end
        local cur = Vector3.new(hrp.Position.X, targetPos.Y, hrp.Position.Z)
        local dir = Vector3.new(targetPos.X - cur.X, 0, targetPos.Z - cur.Z)
        if dir.Magnitude < 0.1 then break end
        dir = dir.Unit
        local dt = RunService.Heartbeat:Wait()
        local step = dir * getWalkSpeed() * dt
        if step.Magnitude > distLeft() then step = dir * distLeft() end
        local newPos = cur + step
        local cf = keepRot and CFrame.new(newPos) * (hrp.CFrame - hrp.CFrame.Position) or (lookAt and CFrame.lookAt(newPos, lookAt) or CFrame.lookAt(newPos, newPos + dir))
        hrp.CFrame = cf
        hrp.AssemblyLinearVelocity = Vector3.zero
    end
end
local function walkFallback(targetPos, keepRot)
    local hrp = findHRP(plr.Character)
    if not hrp or not targetPos then return false end
    pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero end)
    local function distLeft() return (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(targetPos.X, 0, targetPos.Z)).Magnitude end
    if distLeft() < 1.2 then return true end
    while distLeft() > 1.2 do
        if not plr.Character or not hrp.Parent then return false end
        if not isDropVisible() then return false end
        local cur = Vector3.new(hrp.Position.X, targetPos.Y, hrp.Position.Z)
        local dir = Vector3.new(targetPos.X - cur.X, 0, targetPos.Z - cur.Z)
        if dir.Magnitude < 0.1 then break end
        dir = dir.Unit
        local dt = RunService.Heartbeat:Wait()
        local step = dir * getWalkSpeed() * dt
        if step.Magnitude > distLeft() then step = dir * distLeft() end
        local newPos = cur + step
        hrp.CFrame = keepRot and CFrame.new(newPos) * (hrp.CFrame - hrp.CFrame.Position) or CFrame.lookAt(newPos, newPos + dir)
        hrp.AssemblyLinearVelocity = Vector3.zero
    end
    return true
end
local function walkDefend(targetPos, mode)
    if mode == "None" or not mode then return walkFallback(targetPos, true) end
    local hrp = findHRP(plr.Character)
    if not hrp then return false end
    local start = Vector3.new(hrp.Position.X, targetPos.Y, hrp.Position.Z)
    local dir = targetPos - start
    local dist = Vector3.new(dir.X, 0, dir.Z).Magnitude
    if dist < 5 then return walkFallback(targetPos, true) end
    dir = Vector3.new(dir.X, 0, dir.Z).Unit
    local perp = Vector3.new(-dir.Z, 0, dir.X)
    local pts = {}
    if mode == "ZigZag" then for i = 1, 4 do local t = i / 5 table.insert(pts, start:Lerp(targetPos, t) + perp * ((i % 2 == 0 and 1 or -1) * 10)) end
    elseif mode == "Random" then for i = 1, 4 do local t = i / 5 table.insert(pts, start:Lerp(targetPos, t) + perp * math.random(-12, 12)) end
    elseif mode == "Circle" then for i = 1, 6 do local t = i / 7 local a = i * 60 table.insert(pts, start:Lerp(targetPos, t) + Vector3.new(math.cos(math.rad(a)) * 8, 0, math.sin(math.rad(a)) * 8)) end
    elseif mode == "Juke" then for i = 1, 5 do local t = i / 6 table.insert(pts, start:Lerp(targetPos, t) + perp * ((i % 2 == 0 and 14 or -14) + math.random(-4, 4))) end end
    for _, p in ipairs(pts) do if not walkFallback(p, true) then return false end task.wait(0.05) end
    return walkFallback(targetPos, true)
end
local function walkToSafeFallback()
    if not walkDefend(SAFE_BASE_MID, defendMode) then tpTo(SAFE_BASE_CF) return true end
    tpTo(SAFE_BASE_CF) task.wait(0.08) tpTo(SAFE_BASE_CF)
    return true
end
local function walkToSafe()
    if defendMode == "None" then tpTo(SAFE_BASE_CF) else walkDirect(SAFE_BASE_MID, nil, true) tpTo(SAFE_BASE_CF) end
end

-- ============ PROMPT SATUIN ============
local function makeBigPrompt(p)
    if not p:IsA("ProximityPrompt") then return end
    pcall(function() p.HoldDuration = 0 p.MaxActivationDistance = RANGE p.RequiresLineOfSight = false p.KeyboardKeyCode = Enum.KeyCode.E p.Exclusivity = Enum.ProximityPromptExclusivity.OnePerButton end)
end
local function firePrompt(p)
    if not p:IsA("ProximityPrompt") then return end
    makeBigPrompt(p)
    if fireproximityprompt then pcall(fireproximityprompt, p, 0) end
    pcall(function() p:InputHoldBegin() task.wait(0.05) p:InputHoldEnd() end)
end
local function anchorPosOf(pr)
    if not pr then return nil end
    local p = pr.Parent
    if not p then return nil end
    if p:IsA("Attachment") then return p.WorldPosition end
    if p:IsA("BasePart") then return p.Position end
    if p:IsA("Model") then return posOf(p) end
    -- Parent bisa Folder / part lain: cari BasePart di dalam parent prompt-nya
    local bp = p:FindFirstChildWhichIsA("BasePart", true)
    if bp then return bp.Position end
    return nil
end
local function promptNear(m, md)
    -- FIX: Prompt STEAL BUKAN di dalam model. Jangan cari di m:GetDescendants().
    -- Prompt-nya nempel di part lain di workspace, deket posisi model.
    -- Jadi carinya: scan ProximityPrompt "steal" di workspace, ambil yang anchor-nya paling deket sama pos model.
    if not m then return nil end
    local bp = posOf(m)
    if not bp then return nil end
    local best, mn = nil, md or 15
    for _, v in ipairs(workspace:GetDescendants()) do
        if v:IsA("ProximityPrompt") and v.Name:lower():find("steal") then
            local ap = anchorPosOf(v)
            if ap then
                local d = (Vector3.new(ap.X, 0, ap.Z) - Vector3.new(bp.X, 0, bp.Z)).Magnitude
                if d <= mn then mn = d best = v end
            end
        end
    end
    return best
end
local function fireSteal(m)
    -- FIX: Prompt STEAL BUKAN di dalam model, jadi jangan scan m:GetDescendants().
    -- Ambil prompt terdekat dari workspace lewat promptNear, terus fire itu.
    if not m or not m.Parent then return end
    local pr = promptNear(m, 15)
    if pr then firePrompt(pr) end
end
local function touchSteal(m)
    if not m or not m.Parent then return end
    local hrp = findHRP(plr.Character)
    local part = nil
    if m:IsA("BasePart") then part = m elseif m:IsA("Model") then part = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart") else part = m:FindFirstChildWhichIsA("BasePart", true) end
    if hrp and part then pcall(function() firetouchinterest(hrp, part, 0) task.wait(0.02) firetouchinterest(hrp, part, 1) end) end
end
local function pressE() pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game) task.wait(0.05) VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game) end) end
local function closestPlayerTo(m, maxDist)
    local pos = posOf(m)
    if not pos then return nil end
    local best, md = nil, maxDist or 20
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= plr and p.Character and findHRP(p.Character) then
            local hrp = findHRP(p.Character)
            local d = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
            if d < md then md = d best = p end
        end
    end
    return best
end
local function equipBat()
    local char = plr.Character if not char then return nil end
    local bat = char:FindFirstChildWhichIsA("Tool")
    if bat and bat.Name:lower():find("bat") then return bat end
    for _, t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("bat") then t.Parent = char return t end end
    for _, t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent = char return t end end
    return char:FindFirstChildOfClass("Tool")
end
local function attackCarrier(carrier)
    if not attackEnabled or not carrier or not carrier.Character then return end
    local hrp = findHRP(carrier.Character)
    if not hrp then return end
    for _ = 1, 20 do
        if not carrier.Character.Parent or not attackEnabled then break end
        local myHrp = findHRP(plr.Character)
        if not myHrp then break end
        local pred = hrp.Position + hrp.CFrame.LookVector * 5
        walkDirect(Vector3.new(pred.X, 3.5, pred.Z), hrp.Position, false)
        local bat = equipBat()
        if bat then pcall(function() bat:Activate() end) pcall(function() VIM:SendMouseButtonEvent(0, 0, 0, true, game, 0) task.wait(0.05) VIM:SendMouseButtonEvent(0, 0, 0, false, game, 0) end) end
        task.wait(0.15)
        if (Vector3.new(myHrp.Position.X, 0, myHrp.Position.Z) - Vector3.new(hrp.Position.X, 0, hrp.Position.Z)).Magnitude > 30 then break end
    end
end
local function notify(t, c) Window:Notify({ Title = t, Content = c, Duration = 2 }) end
local stealMode = "Normal"
local function stealMethod(m)
    if not m or not m.Parent then return end
    notify(m.Name, (m:GetAttribute("Rarity") or "Unknown") .. " - " .. cashTxt(m))
    local lastPos = posOf(m) local tries = 0
    while tries < 8 and m.Parent do
        if isDropVisible() then if not isCarryingTarget(m) then fireDropNow() task.wait(0.35) tries += 1 continue else break end end
        local curPos = posOf(m)
        if curPos and lastPos and (curPos - lastPos).Magnitude > 2 then local car = closestPlayerTo(m, 20) if car and attackEnabled then attackCarrier(car) end end
        lastPos = curPos local p, b = offsetPosOf(m) if p then walkDirect(p, b, false) end touchSteal(m) fireSteal(m) pressE() task.wait(0.25) tries += 1
        if isDropVisible() and not isCarryingTarget(m) then fireDropNow() task.wait(0.3) end
    end
    if not isDropVisible() then walkToSafe() return end
    if not isCarryingTarget(m) then fireDropNow() task.wait(0.3) return end
    if stealMode == "Helper" then if not walkDefend(HELPER_DROP_POS, defendMode) then return end if not isCarryingTarget(m) then fireDropNow() return end task.wait(0.15) fireDropNow() task.wait(0.2) walkToSafeFallback()
    else walkToSafeFallback() end
end

-- ============ ESP SATUIN ============
local function espAdd(cache, model, color, title, sub, sub2)
    if not model or not model.Parent or cache[model] or not model:IsA("Model") then return end
    local ad = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
    if not ad then return end
    local hl = Instance.new("Highlight") hl.Name = "SoruEspHL" hl.Adornee = model hl.FillColor = color hl.OutlineColor = color hl.FillTransparency = 0.65 hl.OutlineTransparency = 0 hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop hl.Parent = model
    local bb = Instance.new("BillboardGui") bb.Name = "SoruEspBB" bb.Adornee = ad bb.Size = UDim2.fromOffset(165, 56) bb.StudsOffset = Vector3.new(0, 4.2, 0) bb.AlwaysOnTop = true bb.Parent = ad
    local f = Instance.new("Frame", bb) f.Size = UDim2.new(1, 0, 1, 0) f.BackgroundColor3 = Color3.fromRGB(20, 18, 32) f.BackgroundTransparency = 0.12 Instance.new("UICorner", f).CornerRadius = UDim.new(0, 8)
    local st = Instance.new("UIStroke", f) st.Color = color st.Transparency = 0.2 st.Thickness = 1
    local n = Instance.new("TextLabel", f) n.Size = UDim2.new(1, -8, 0, 14) n.Position = UDim2.new(0, 5, 0, 4) n.BackgroundTransparency = 1 n.Text = title n.Font = Enum.Font.GothamBold n.TextSize = 10 n.TextColor3 = Color3.new(1, 1, 1) n.TextXAlignment = Enum.TextXAlignment.Left n.TextTruncate = Enum.TextTruncate.AtEnd
    local a = Instance.new("TextLabel", f) a.Size = UDim2.new(1, -8, 0, 11) a.Position = UDim2.new(0, 5, 0, 18) a.BackgroundTransparency = 1 a.Text = sub a.Font = Enum.Font.GothamMedium a.TextSize = 9 a.TextColor3 = color a.TextXAlignment = Enum.TextXAlignment.Left
    local b = Instance.new("TextLabel", f) b.Size = UDim2.new(1, -8, 0, 10) b.Position = UDim2.new(0, 5, 0, 30) b.BackgroundTransparency = 1 b.Text = sub2 b.Font = Enum.Font.GothamMedium b.TextSize = 8 b.TextColor3 = DIM b.TextXAlignment = Enum.TextXAlignment.Left
    cache[model] = { hl = hl, bb = bb }
end
local function espDel(cache, model)
    local d = cache[model]
    if d then pcall(function() if d.hl then d.hl:Destroy() end end) pcall(function() if d.bb then d.bb:Destroy() end end) cache[model] = nil end
end
local function espClear(cache) for m, _ in pairs(cache) do espDel(cache, m) end table.clear(cache) end
local function createAnimalEsp(m)
    local r = m:GetAttribute("Rarity") or "Unknown"
    if next(selectedEspRarity) ~= nil and not selectedEspRarity[r] then return end
    local w = m:GetAttribute("WeightKg") or m:GetAttribute("Weight") or 0
    espAdd(espCache, m, rarityColor(r), m.Name:upper(), string.upper(r) .. " • " .. cashTxt(m), tostring(w) .. " KG • " .. zoneOf(m))
end
local function refreshAnimalEsp()
    if not espEnabled then espClear(espCache) return end
    local folder = workspace:FindFirstChild("AnimalPickups")
    if not folder then return end
    for _, m in ipairs(folder:GetChildren()) do if m:IsA("Model") then local r = m:GetAttribute("Rarity") or "Unknown" if next(selectedEspRarity) == nil or selectedEspRarity[r] then createAnimalEsp(m) else espDel(espCache, m) end end end
    for m, _ in pairs(espCache) do if not m.Parent then espDel(espCache, m) end end
end

-- ============ EGG ============
local function eggSize(m)
    for _, a in ipairs({ "Size", "EggSize", "Scale", "WeightKg", "Weight", "SizeMultiplier" }) do local v = m:GetAttribute(a) if typeof(v) == "number" then return v end end
    for _, d in ipairs(m:GetDescendants()) do if d:IsA("NumberValue") and d.Name:lower():find("size") then return d.Value end end
    local ok, _, sz = pcall(function() return m:GetBoundingBox() end)
    if ok and sz then return sz.Magnitude end
    return 0
end
local function eggCat(m)
    local s = eggSize(m)
    if s < 8 then return "Small" elseif s < 16 then return "Standar" elseif s < 28 then return "Big" else return "Titan" end
end
local function eggsInZone(zoneName)
    local zb = zoneFolder()
    if not zb then return {} end
    local zm = zb:FindFirstChild(zoneName)
    if not zm then return {} end
    local root = zm:FindFirstChild("Eggs") or zm
    local out = {}
    for _, v in ipairs(root:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out, v) end end
    if #out == 0 then for _, v in ipairs(root:GetDescendants()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out, v) end end end
    if bigEggPriority then table.sort(out, function(a, b) return eggSize(a) > eggSize(b) end) end
    return out
end
local function allEggs()
    local zb = zoneFolder()
    if not zb then return {} end
    local out = {}
    for _, z in ipairs(zb:GetChildren()) do if z:IsA("Model") then for _, e in ipairs(eggsInZone(z.Name)) do table.insert(out, e) end end end
    return out
end
local function zoneTeleportPos(zoneName)
    local eggs = eggsInZone(zoneName)
    if #eggs > 0 then local p = posOf(eggs[1]) if p then return Vector3.new(p.X, 5, p.Z) end end
    local zb = zoneFolder()
    if zb then local zm = zb:FindFirstChild(zoneName) if zm then local p = posOf(zm) if p then return Vector3.new(p.X, 5, p.Z) end end end
    return nil
end
local function createEggEsp(m)
    if next(selectedEggZones) ~= nil and not selectedEggZones[zoneOf(m)] then return end
    local cat = eggCat(m)
    if next(selectedEggSizes) ~= nil and not selectedEggSizes[cat] then return end
    local col = cat == "Titan" and Color3.fromRGB(255, 60, 60) or cat == "Big" and Color3.fromRGB(255, 180, 0) or cat == "Standar" and Color3.fromRGB(85, 170, 255) or Color3.fromRGB(180, 180, 180)
    espAdd(eggEspCache, m, col, m.Name:upper(), cat .. " • " .. zoneOf(m), "")
end
local function refreshEggEsp()
    if not eggEspEnabled then espClear(eggEspCache) return end
    for _, m in ipairs(allEggs()) do createEggEsp(m) end
    for m, _ in pairs(eggEspCache) do if not m.Parent then espDel(eggEspCache, m) end end
end

