aPlot:Toggle( { Title = "Equip Best", Flag = "EquipBest", Default = false, Callback = function(v) if v then task.spawn(function() while v do pcall(function() game.ReplicatedStorage.PetsInventoryRemote:FireServer("EquipBest", nil) end) task.wait(1.5) end end) end end })
local aIndex = TabPlot:Accordion( { Title = "Index", Icon = "list", Column = 2 })
aIndex:Toggle( { Title = "Claim Index", Flag = "ClaimIndex", Default = false, Callback = function(v) if v then task.spawn(function() while v do pcall(function() game.ReplicatedStorage.IndexRemote:FireServer("ClaimAll", nil) end) task.wait(2) end end) end end })

-- BLATANT
local aBlatant = TabBlatant:Accordion( { Title = "Steal", Icon = "zap", Column = 1 })
aBlatant:Button( { Title = "Instant Steal", Callback = function()
    local list = sortedAnimals()
    if #list == 0 then return end
    instantSteal(list[1].model)
end })
local aTP = TabBlatant:Accordion( { Title = "Teleport", Icon = "target", Column = 2 })
aTP:Dropdown( { Title = "Zone", Flag = "TeleportZone", Options = zoneNames, Default = nil, Callback = function(val) selectedTeleportZone = unwrap(val) end })
aTP:Button( { Title = "Teleport", Callback = function()
    if not selectedTeleportZone then notify("Error", "Zone kosong") return end
    pendingTeleportZone = selectedTeleportZone
    notify("Teleport", "Reset ke " .. selectedTeleportZone)
    local char = plr.Character
    if char then local hum = findHumanoid(char) if hum then hum.Health = 0 else char:BreakJoints() end end
end })

-- UPGRADE
local aTread = TabUpgrade:Accordion( { Title = "Auto Treadmill", Icon = "gauge", Column = 1 })
local treadOn = false
aTread:Toggle( { Title = "Auto Upgrade", Flag = "AutoTreadmill", Default = false, Callback = function(v) treadOn = v if treadOn then task.spawn(function() while treadOn do pcall(function() game.ReplicatedStorage.UpgradeTreadmillRequest:FireServer() end) task.wait(1) end end) end end })
local aPlotUp = TabUpgrade:Accordion( { Title = "Auto Plot", Icon = "box", Column = 2 })
local plotUpOn = false
aPlotUp:Toggle( { Title = "Auto Upgrade", Flag = "AutoPlotUpgrade", Default = false, Callback = function(v) plotUpOn = v if plotUpOn then task.spawn(function() while plotUpOn do pcall(function() game.ReplicatedStorage.UpgradePlotRequest:FireServer() end) task.wait(1) end end) end end })

-- DIAMOND
local aDiamond = TabDiamond:Accordion( { Title = "Farm Egg", Icon = "pickaxe", Column = 1 })
aDiamond:Dropdown( { Title = "Zone", Flag = "DiamondZone", Options = zoneNames, Default = nil, Callback = function(val) diamondZone = unwrap(val) end })
aDiamond:Slider( { Title = "Farm Egg", Flag = "DiamondFarmSpeed", Min = 16, Max = 500, Default = 60, Suffix = " stud/s", Callback = function(v) diamondFarmSpeed = v end })
aDiamond:Toggle( { Title = "Farm Diamond", Flag = "FarmDiamond", Default = false, Callback = function(v)
    diamondOn = v
    if diamondOn then if not diamondZone then notify("Error", "Zone kosong") diamondOn = false return end task.spawn(diamondLoop) else if diamondTween then pcall(function() diamondTween:Cancel() end) diamondTween = nil end end
end })
local aDInfo = TabDiamond:Accordion( { Title = "Info", Icon = "info", Column = 2 })
aDInfo:Paragraph( { Title = "Cara kerja", Desc = "Gem dulu sampe habis, baru break." })
aDInfo:Label( "Matikan Break Egg di Main biar ga rebutan.")

-- ============ PANEL ============
local panel = Window:Panel({ Title = "Animal Tracker", Subtitle = "Top animals \u2022 Steal", Width = 360, OpenDrag = "Left", GripY = 0.5, Open = false })
local pCtrl = panel:Accordion( { Title = "Tracker", Icon = "eye" })
pCtrl:Dropdown( { Title = "Mode", Flag = "TrackerMode", Options = { "Blatant", "Legit" }, Default = "Blatant", Callback = function(val) trackerMode = unwrap(val) or "Blatant" end })
local pTotal = pCtrl:Info( { Title = "Total Animals", Value = "0" })
pCtrl:Button( { Title = "Steal Best", Callback = function() stealByRank(1) end })
local function topCard(title)
    local c = panel:Accordion( { Title = title, Icon = "star" })
    local n = c:Info( { Title = "Animal", Value = "-" })
    local cash = c:Info( { Title = "$ /s", Value = "-" })
    local det = c:Label( "Rarity • Zone • KG")
    return c, n, cash, det
end
local c1, n1, cash1, d1 = topCard("TOP 1 • $ Tertinggi")
c1:Button( { Title = "STEAL TOP 1", Callback = function() stealByRank(1) end })
local c2, n2, cash2, d2 = topCard("TOP 2")
c2:Button( { Title = "STEAL TOP 2", Callback = function() stealByRank(2) end })
local c3, n3, cash3, d3 = topCard("TOP 3")
c3:Button( { Title = "STEAL TOP 3", Callback = function() stealByRank(3) end })
task.spawn(function()
    while task.wait(0.6) do
        pcall(function()
            local list = sortedAnimals()
            if pTotal then pTotal:Set(tostring(#list)) end
            local function setCard(idx, ni, ci, di)
                local info = list[idx]
                if info and info.model and info.model.Parent then
                    local m = info.model ni:Set(m.Name) ci:Set(info.txt)
                    local rar = m:GetAttribute("Rarity") or "Unknown"
                    local w = m:GetAttribute("WeightKg") or m:GetAttribute("Weight") or 0
                    di:Set(tostring(rar) .. " • " .. zoneOf(m) .. " • " .. tostring(w) .. " KG")
                else ni:Set("-") ci:Set("-") di:Set("Rarity • Zone • KG") end
            end
            setCard(1, n1, cash1, d1) setCard(2, n2, cash2, d2) setCard(3, n3, cash3, d3)
        end)
    end
end)

-- ============ CHARACTER / LOOP, TANPA WaitForChild ============
plr.CharacterAdded:Connect(function(char)
    task.wait(0.5)
    local hum = nil local t = 0
    while not hum and t < 1.5 do hum = findHumanoid(char) task.wait(0.1) t += 0.1 end
    if hum then local rs = hum.WalkSpeed sliderSpeed = rs hum:SetAttribute("BaseSpeed", rs) if walkSliderRef then walkSliderRef:Set(rs) end end
    task.wait(0.5)
    if autoRagdollOn then startRagdoll() end
    if fastBreakOn then setFastBreak(true) end
    if clearOnRespawn then espClear(espCache) espClear(eggEspCache) end
    if espEnabled then task.wait(0.5) refreshAnimalEsp() end
    if eggEspEnabled then task.wait(0.5) refreshEggEsp() end
end)
plr.CharacterAdded:Connect(function(char)
    if pendingTeleportZone then
        local zn = pendingTeleportZone
        local hrp = nil local t = 0
        while not hrp and t < 1.5 do hrp = findHRP(char) task.wait(0.1) t += 0.1 end
        if hrp then task.wait(0.2) local pos = zoneTeleportPos(zn) if pos then tpTo(pos) task.wait(0.15) tpTo(pos) end end
        pendingTeleportZone = nil
    end
end)
RunService.Heartbeat:Connect(function()
    local hum = findHumanoid(plr.Character)
    if hum and math.abs(hum.WalkSpeed - sliderSpeed) > 0.1 then hum.WalkSpeed = sliderSpeed end
end)
